(()=>{"use strict";const e=document.querySelector(".ham-menu"),t=document.querySelector(".off-screen-menu"),c=document.querySelectorAll(".off-screen-menu h3 a");e.addEventListener("click",()=>{e.classList.toggle("active"),t.classList.toggle("active"),document.body.classList.toggle("no-scroll")}),c.forEach(c=>{c.addEventListener("click",()=>{t.classList.toggle("active"),e.classList.toggle("active"),document.body.classList.toggle("no-scroll")})})})();